-- Tables isolées pour les rosters ATYOM ; aucun changement GX NØVA.
create table if not exists public.atyom_roster_players (id uuid primary key default gen_random_uuid(), roster_id text not null references public.atyom_rosters(id) on delete cascade,display_name text not null check (char_length(trim(display_name)) between 2 and 40),shirt_number smallint check (shirt_number between 1 and 99),preferred_position text not null default 'POLY' check (preferred_position ~ '^[A-Z0-9]{2,6}$'),is_active boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists atyom_roster_players_unique_name on public.atyom_roster_players(roster_id,lower(trim(display_name)));
create index if not exists atyom_roster_players_active on public.atyom_roster_players(roster_id,is_active,display_name);
alter table public.atyom_roster_players enable row level security;
create table if not exists public.atyom_roster_lineups (roster_id text primary key references public.atyom_rosters(id) on delete cascade,formation text not null default '4-3-3',assignments jsonb not null default '{}'::jsonb,bench jsonb not null default '[]'::jsonb,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now(),constraint atyom_roster_lineups_assignment_object check(jsonb_typeof(assignments)='object'),constraint atyom_roster_lineups_bench_array check(jsonb_typeof(bench)='array'));
alter table public.atyom_roster_lineups enable row level security;
